class ComboSystem {
  private comboCount: number = 0;
  private comboTimer: number = 0;
  private readonly COMBO_WINDOW = 5; // 5秒连击窗口

  onCatch(itemValue: number): number {
    if (this.comboTimer > 0) {
      this.comboCount++;
    } else {
      this.comboCount = 1;
    }
    this.comboTimer = this.COMBO_WINDOW;

    const multiplier = this.getMultiplier();
    return itemValue * multiplier;
  }

  private getMultiplier(): number {
    if (this.comboCount >= 5) return 3.0;
    if (this.comboCount >= 3) return 2.0;
    if (this.comboCount >= 2) return 1.5;
    return 1.0;
  }

  update(deltaTime: number) {
    if (this.comboTimer > 0) {
      this.comboTimer -= deltaTime;
      if (this.comboTimer <= 0) {
        this.comboCount = 0; // 连击中断
      }
    }
  }
}

class DPSTracker {
  private totalScore: number = 0;
  private totalTime: number = 0;
  private sessionScores: number[] = [];

  recordCatch(score: number, timeSpent: number) {
    this.totalScore += score;
    this.totalTime += timeSpent;
    this.sessionScores.push(score / timeSpent);
  }

  getDPS(): number {
    if (this.totalTime === 0) return 0;
    return this.totalScore / this.totalTime;
  }

  getPeakDPS(): number {
    return Math.max(...this.sessionScores, 0);
  }

  getAverageDPS(): number {
    if (this.sessionScores.length === 0) return 0;
    const sum = this.sessionScores.reduce((a, b) => a + b, 0);
    return sum / this.sessionScores.length;
  }
}

class ResourceManager {
  private gold: number = 100;
  private diamond: number = 0;
  private energy: number = 100;

  // 资源循环入口
  startGame(cost: number): boolean {
    if (this.energy >= cost) {
      this.energy -= cost;
      return true;
    }
    return false;
  }

  // 产出资源
  addResources(item: CollectibleItem, combo: number) {
    const baseValue = item.value;
    const comboMultiplier = 1 + (combo * 0.5);
    const earnedGold = Math.floor(baseValue * comboMultiplier);

    this.gold += earnedGold;
    this.energy += 5; // 每次抓取回复少量体力

    // 稀有物品额外产出
    if (item.rarity === 'legendary') {
      this.diamond += 1;
    }

    return earnedGold;
  }

  // 消耗资源（资源下沉）
  spendGold(amount: number): boolean {
    if (this.gold >= amount) {
      this.gold -= amount;
      return true;
    }
    return false;
  }

  // 购买增益卡牌
  buyCard(card: Card): boolean {
    if (this.spendGold(card.price)) {
      return true;
    }
    // 钻石补偿购买
    const diamondPrice = Math.ceil(card.price / 100);
    if (this.diamond >= diamondPrice) {
      this.diamond -= diamondPrice;
      return true;
    }
    return false;
  }
}
